14	fn to_type_ref(type_of: &Type) -> dynamic::TypeRef {
15	  match type_of {
16	    Type::NamedType { name, non_null } => {
17	      if *non_null {
18	        dynamic::TypeRef::NonNull(Box::from(dynamic::TypeRef::Named(Cow::Owned(name.clone()))))
19	      } else {
20	        dynamic::TypeRef::Named(Cow::Owned(name.clone()))
21	      }
22	    }
23	    Type::ListType { of_type, non_null } => {
24	      let inner = Box::new(to_type_ref(of_type));
25	      if *non_null {
26	        dynamic::TypeRef::NonNull(Box::from(dynamic::TypeRef::List(inner)))
27	      } else {
28	        dynamic::TypeRef::List(inner)
29	      }
30	    }
31	  }
32	}
