34	fn get_cache_key<'a, H: Hasher + Clone>(
35	  ctx: &'a EvaluationContext<'a, ResolverContext<'a>>,
36	  mut hasher: H,
37	) -> Option<u64> {
38	  // Hash on parent value
39	  if let Some(const_value) = ctx
40	    .graphql_ctx
41	    .parent_value
42	    .as_value()
43	    // TODO: handle _id, id, or any field that has @key on it.
44	    .filter(|value| value != &&ConstValue::Null)
45	    .map(|data| data.get_key("id"))
46	  {
47	    // Hash on parent's id only?
48	    helpers::value::hash(const_value?, &mut hasher);
49	  }
50	
51	  let key = ctx
52	    .graphql_ctx
53	    .args
54	    .iter()
55	    .map(|(key, value)| {
56	      let mut hasher = hasher.clone();
57	      key.hash(&mut hasher);
58	      helpers::value::hash(value.as_value(), &mut hasher);
59	      hasher.finish()
60	    })
61	    .fold(hasher.finish(), |acc, val| acc ^ val);
62	
63	  Some(key)
64	}
