66	fn to_type(def: &Definition) -> dynamic::Type {
67	  match def {
68	    Definition::ObjectTypeDefinition(def) => {
69	      let mut object = dynamic::Object::new(def.name.clone());
70	      for field in def.fields.iter() {
71	        let field = field.clone();
72	        let type_ref = to_type_ref(&field.of_type);
73	        let field_name = &field.name.clone();
74	        let cache = field.cache.clone();
75	        let mut dyn_schema_field = dynamic::Field::new(field_name, type_ref, move |ctx| {
76	          let req_ctx = ctx.ctx.data::<Arc<RequestContext>>().unwrap();
77	          let field_name = &field.name;
78	          match &field.resolver {
79	            None => {
80	              let ctx = EvaluationContext::new(req_ctx, &ctx);
81	              FieldFuture::from_value(ctx.path_value(&[field_name]).map(|a| a.to_owned()))
82	            }
83	            Some(expr) => {
84	              let expr = expr.to_owned();
85	              let cache = cache.clone();
86	              FieldFuture::new(async move {
87	                let ctx = EvaluationContext::new(req_ctx, &ctx);
88	
89	                let ttl_and_key =
90	                  cache.and_then(|Cache { max_age: ttl, hasher }| Some((ttl, get_cache_key(&ctx, hasher)?)));
91	                let const_value = match ttl_and_key {
92	                  Some((ttl, key)) => {
93	                    if let Some(const_value) = ctx.req_ctx.cache_get(&key) {
94	                      // Return value from cache
95	                      log::info!("Reading from cache. key = {key}");
96	                      const_value
97	                    } else {
98	                      let const_value = expr.eval(&ctx, &Concurrent::Sequential).await?;
99	                      log::info!("Writing to cache. key = {key}");
100	                      // Write value to cache
101	                      ctx.req_ctx.cache_insert(key, const_value.clone(), ttl);
102	                      const_value
103	                    }
104	                  }
105	                  _ => expr.eval(&ctx, &Concurrent::Sequential).await?,
106	                };
107	
108	                let p = match const_value {
109	                  ConstValue::List(a) => FieldValue::list(a),
110	                  a => FieldValue::from(a),
111	                };
112	                Ok(Some(p))
113	              })
114	            }
115	          }
116	        });
117	        if let Some(description) = &field.description {
118	          dyn_schema_field = dyn_schema_field.description(description);
119	        }
120	        for arg in field.args.iter() {
121	          dyn_schema_field =
122	            dyn_schema_field.argument(dynamic::InputValue::new(arg.name.clone(), to_type_ref(&arg.of_type)));
123	        }
124	        object = object.field(dyn_schema_field);
125	      }
126	      for interface in def.implements.iter() {
127	        object = object.implement(interface.clone());
128	      }
129	
130	      dynamic::Type::Object(object)
131	    }
132	    Definition::InterfaceTypeDefinition(def) => {
133	      let mut interface = dynamic::Interface::new(def.name.clone());
134	      for field in def.fields.iter() {
135	        interface = interface.field(dynamic::InterfaceField::new(
136	          field.name.clone(),
137	          to_type_ref(&field.of_type),
138	        ));
139	      }
140	
141	      dynamic::Type::Interface(interface)
142	    }
143	    Definition::InputObjectTypeDefinition(def) => {
144	      let mut input_object = dynamic::InputObject::new(def.name.clone());
145	      for field in def.fields.iter() {
146	        input_object = input_object.field(dynamic::InputValue::new(
147	          field.name.clone(),
148	          to_type_ref(&field.of_type),
149	        ));
150	      }
151	
152	      dynamic::Type::InputObject(input_object)
153	    }
154	    Definition::ScalarTypeDefinition(def) => {
155	      let mut scalar = dynamic::Scalar::new(def.name.clone());
156	      if let Some(description) = &def.description {
157	        scalar = scalar.description(description);
158	      }
159	      dynamic::Type::Scalar(scalar)
160	    }
161	    Definition::EnumTypeDefinition(def) => {
162	      let mut enum_type = dynamic::Enum::new(def.name.clone());
163	      for value in def.enum_values.iter() {
164	        enum_type = enum_type.item(dynamic::EnumItem::new(value.name.clone()));
165	      }
166	      dynamic::Type::Enum(enum_type)
167	    }
168	    Definition::UnionTypeDefinition(def) => {
169	      let mut union = dynamic::Union::new(def.name.clone());
170	      for type_ in def.types.iter() {
171	        union = union.possible_type(type_.clone());
172	      }
173	      dynamic::Type::Union(union)
174	    }
175	  }
176	}
